begin
  if to_regclass('public.investor_financial_legacy_imports') is null then
    raise exception 'Execute primeiro MIGRACAO-INVESTIDOR-ETAPA-8-HISTORICO-PLANILHA.sql';
  end if;

  select count(*), (array_agg(i.id))[1]
  into v_matches, v_investor_id
  from public.investors i
  join auth.users u on lower(trim(coalesce(u.email, ''))) = lower(trim(coalesce(i.email, '')))
  join public.admin_users a on a.id = u.id
  where i.active = true
    and coalesce(trim(i.email), '') <> '';

  if v_matches = 0 then
    raise exception 'Nenhum investidor ativo com o mesmo e-mail de uma conta administrativa foi encontrado. Vincule primeiro a sua conta Admin + Investidor.';
  end if;

  if v_matches > 1 then
    raise exception 'Foram encontrados % investidores Admin + Investidor. A importação foi cancelada para não colocar o histórico na conta errada.', v_matches;
  end if;

  if exists (
    select 1 from public.investor_financial_legacy_imports
    where investor_id = v_investor_id and source_name = v_source
  ) then
    raise exception 'Esta planilha já foi importada para este investidor. Nada foi duplicado.';
  end if;

  insert into public.investor_financial_legacy_imports(
    investor_id, source_name, source_version, summary, notes
  ) values (
    v_investor_id,
    v_source,
    'Etapa 8 / 31-08-2026',
    v_summary,
    'Importação do histórico anterior. O saldo informado pela planilha foi preservado como ponto de partida. Os registros originais permanecem separados das vendas automáticas do rodízio.'
  )
  returning id into v_import_id;

  insert into public.investor_financial_legacy_stock(
    import_id, investor_id, source_row, item_no, product_name, purchase_date,
    quantity, unit_cost, total_cost, sale_price, profit_per_piece,
    sale_price_percent, gross_revenue, net_profit, profit_percent, raw_data
  )
  select
    v_import_id, v_investor_id, x.source_row, x.item_no, x.product_name,
    nullif(x.purchase_date, '')::date,
    x.quantity, x.unit_cost, x.total_cost, x.sale_price, x.profit_per_piece,
    x.sale_price_percent, x.gross_revenue, x.net_profit, x.profit_percent,
    x.raw
  from jsonb_to_recordset(v_stock) as x(
    source_row integer, item_no text, product_name text, purchase_date text,
    quantity numeric, unit_cost numeric, total_cost numeric, sale_price numeric,
    profit_per_piece numeric, sale_price_percent numeric, gross_revenue numeric,
    net_profit numeric, profit_percent numeric, raw jsonb
  );

  insert into public.investor_financial_legacy_customer_sales(
    import_id, investor_id, source_row, sequence_no, client_raw, product_raw,
    value_raw, obs_raw, amount_numeric, detected_date, status_raw, raw_data
  )
  select
    v_import_id, v_investor_id, x.source_row, x.sequence, x.client_raw,
    x.product_raw, x.value_raw, x.obs_raw, x.amount_numeric,
    nullif(x.detected_date, '')::date, nullif(x.status_raw, ''), x.raw
  from jsonb_to_recordset(v_sales) as x(
    source_row integer, sequence text, client_raw text, product_raw text,
    value_raw text, obs_raw text, amount_numeric numeric, detected_date text,
    status_raw text, raw jsonb
  );

  insert into public.investor_financial_legacy_product_sales(
    import_id, investor_id, source_row, product_name, qty_sold, received,
    profit, contribution_10pct, raw_data
  )
  select
    v_import_id, v_investor_id, x.source_row, x.product_name, x.qty_sold,
    x.received, x.profit, x.contribution, x.raw
  from jsonb_to_recordset(v_product_sales) as x(
    source_row integer, product_name text, qty_sold numeric, received numeric,
    profit numeric, contribution numeric, raw jsonb
  );

  insert into public.investor_financial_legacy_expenses(
    import_id, investor_id, source_row, sequence_no, description, amount, raw_data
  )
  select
    v_import_id, v_investor_id, x.source_row, x.sequence, x.description,
    x.amount, x.raw
  from jsonb_to_recordset(v_expenses) as x(
    source_row integer, sequence text, description text, amount numeric, raw jsonb
  );

  insert into public.investor_financial_legacy_stock_positions(
    import_id, investor_id, source_row, sequence_no, product_name,
    qty_total, qty_sold, qty_available, raw_data
  )
  select
    v_import_id, v_investor_id, x.source_row, x.sequence, x.product_name,
    x.qty_total, x.qty_sold, x.qty_available, x.raw
  from jsonb_to_recordset(v_positions) as x(
    source_row integer, sequence text, product_name text,
    qty_total numeric, qty_sold numeric, qty_available numeric, raw jsonb
  );

  insert into public.investor_financial_audit(
    investor_id, action, entity_type, entity_id, metadata
  ) values (
    v_investor_id,
    'legacy_spreadsheet.import',
    'legacy_import',
    v_import_id,
    jsonb_build_object(
      'source', v_source,
      'estoque_rows', jsonb_array_length(v_stock),
      'vendas_cliente_rows', jsonb_array_length(v_sales),
      'resumo_vendido_rows', jsonb_array_length(v_product_sales),
      'gastos_rows', jsonb_array_length(v_expenses),
      'posicao_estoque_rows', jsonb_array_length(v_positions)
    )
  );
end $$;

commit;

select
  i.name as investidor,
  l.source_name as planilha,
  l.imported_at,
  (select count(*) from public.investor_financial_legacy_stock s where s.import_id=l.id) as linhas_estoque,
  (select count(*) from public.investor_financial_legacy_customer_sales s where s.import_id=l.id) as linhas_vendas_clientes,
  (select count(*) from public.investor_financial_legacy_product_sales s where s.import_id=l.id) as linhas_resumo_vendido,
  (select count(*) from public.investor_financial_legacy_expenses s where s.import_id=l.id) as linhas_gastos,
  (select count(*) from public.investor_financial_legacy_stock_positions s where s.import_id=l.id) as linhas_posicao_estoque,
  'DADOS DA PLANILHA IMPORTADOS COM SUCESSO' as resultado
from public.investor_financial_legacy_imports l
join public.investors i on i.id=l.investor_id
where l.source_name='controle de caixa(4).xlsx'
order by l.imported_at desc
limit 1;
